   350|static void ui_timer(lv_timer_t *timer)
   351|{
   352|  (void)timer;
   353|  uint32_t now = lv_tick_get();
   354|
   355|  /* 心跳：每 2 秒打一次，附带堆剩余量，用于判断是否内存耗尽 */
   356|  {
   357|    static uint32_t last_report;
   358|    if (now - last_report >= 2000u) {
   359|      struct mallinfo mi = mallinfo();
   360|      last_report = now;
   361|      printf("[AURAUI] DIAG tick page=%d free=%d largest=%d\n",
   362|             (int)g_ui.page, (int)mi.fordblks, (int)mi.mxordblk);
   363|    }
   364|  }
   365|
   366|  if (g_ui.page == PAGE_BEAT) {
   367|    aura_body_event_t body;
   368|    aura_judgement_t judgement = aura_game_tick(&g_ui.game, now);
   369|    if (judgement.grade != AURA_GRADE_NONE) update_game_labels(judgement);
   370|    if (aura_body_port_poll(&body)) submit_gesture(body.gesture, now);
   371|    if (g_ui.game.running && g_ui.game.next_note < g_ui.game.note_count) {
   372|      int32_t until = (int32_t)(g_ui.game.started_ms +
   373|          g_ui.game.notes[g_ui.game.next_note].at_ms - now);
   374|      int y = 270 - (until * 100 / 900);
   375|      if (y < 168) y = 168;
   376|      if (y > 285) y = 285;
   377|      lv_obj_set_y(g_ui.note, y);
   378|    }
   379|    finish_game_if_needed();
   380|  } else if (g_ui.page == PAGE_FOCUS) {
