#include "aura_event_bus.h"

#include <string.h>

#define AURA_MAX_SUBSCRIBERS 12

typedef struct {
  aura_event_type_t type;
  aura_event_callback_t callback;
  void *context;
} subscriber_t;

static subscriber_t g_subscribers[AURA_MAX_SUBSCRIBERS];

void aura_event_bus_reset(void)
{
  memset(g_subscribers, 0, sizeof(g_subscribers));
}

bool aura_event_subscribe(aura_event_type_t type, aura_event_callback_t callback,
                          void *context)
{
  size_t i;
  if (type >= AURA_EVENT_COUNT || callback == NULL) {
    return false;
  }
  for (i = 0; i < AURA_MAX_SUBSCRIBERS; i++) {
    if (g_subscribers[i].callback == NULL) {
      g_subscribers[i].type = type;
      g_subscribers[i].callback = callback;
      g_subscribers[i].context = context;
      return true;
    }
  }
  return false;
}

void aura_event_publish(const aura_event_t *event)
{
  size_t i;
  if (event == NULL || event->type >= AURA_EVENT_COUNT) {
    return;
  }
  for (i = 0; i < AURA_MAX_SUBSCRIBERS; i++) {
    if (g_subscribers[i].callback != NULL &&
        g_subscribers[i].type == event->type) {
      g_subscribers[i].callback(event, g_subscribers[i].context);
    }
  }
}

