#include "aura_storage.h"

#include <fcntl.h>
#include <string.h>
#include <unistd.h>

#ifndef CONFIG_AURA_SPACE_STATE_PATH
#define CONFIG_AURA_SPACE_STATE_PATH "/data/aura_space.bin"
#endif

#define AURA_STATE_MAGIC 0x41555241u
#define AURA_STATE_VERSION 1u

typedef struct {
  uint32_t magic;
  uint16_t version;
  uint16_t reserved;
  aura_persisted_state_t state;
  uint32_t checksum;
} state_file_t;

static uint32_t checksum32(const uint8_t *data, size_t size)
{
  uint32_t hash = 2166136261u;
  size_t i;
  for (i = 0; i < size; i++) {
    hash ^= data[i];
    hash *= 16777619u;
  }
  return hash;
}

bool aura_storage_load(aura_persisted_state_t *state)
{
  state_file_t file;
  int fd;
  ssize_t count;
  if (state == NULL) {
    return false;
  }
  memset(state, 0, sizeof(*state));
  fd = open(CONFIG_AURA_SPACE_STATE_PATH, O_RDONLY);
  if (fd < 0) {
    return false;
  }
  count = read(fd, &file, sizeof(file));
  close(fd);
  if (count != (ssize_t)sizeof(file) || file.magic != AURA_STATE_MAGIC ||
      file.version != AURA_STATE_VERSION ||
      file.checksum != checksum32((const uint8_t *)&file.state,
                                  sizeof(file.state))) {
    return false;
  }
  *state = file.state;
  return true;
}

bool aura_storage_save(const aura_persisted_state_t *state)
{
  state_file_t file;
  int fd;
  ssize_t count;
  if (state == NULL) {
    return false;
  }
  memset(&file, 0, sizeof(file));
  file.magic = AURA_STATE_MAGIC;
  file.version = AURA_STATE_VERSION;
  file.state = *state;
  file.checksum = checksum32((const uint8_t *)&file.state, sizeof(file.state));
  fd = open(CONFIG_AURA_SPACE_STATE_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0) {
    return false;
  }
  count = write(fd, &file, sizeof(file));
  close(fd);
  return count == (ssize_t)sizeof(file);
