+/* -------------------------------------------------------------------------
+ * 谱面 → 判定系统 的桥接
+ * ==========================================================================
+ * aura_chart_note_t 的 type 字段（AURA_NOTE_UP=0/LEFT=1/RIGHT=2）与
+ * aura_game.h 的 aura_gesture_t（AURA_GESTURE_UP=0/LEFT=1/RIGHT=2）
+ * 编号完全一致，因此可以逐条直接转换。
+ *
+ * 这是报告 3.1 节「谱面解析引擎」与「判定系统」两个模块的对接点：
+ *   谱面（aura_chart）→ aura_game_t → 判定（aura_game_gesture）
+ * ---------------------------------------------------------------------- */
+static bool chart_to_game(const aura_chart_t *chart, aura_game_t *game)
+{
+  aura_note_t notes[AURA_MAX_NOTES];
+  uint16_t i;
+  uint16_t count = chart->note_count;
+
+  if (chart == NULL || game == NULL || count == 0) {
+    return false;
+  }
+  if (count > AURA_MAX_NOTES) {
+    count = AURA_MAX_NOTES;   /* 判定系统容量小于谱面容量时截断 */
+  }
+
+  for (i = 0; i < count; i++) {
+    notes[i].at_ms = chart->notes[i].at_ms;
+    notes[i].gesture = (aura_gesture_t)chart->notes[i].type;
+  }
+
+  return aura_game_load(game, notes, count);
+}
+
