+           (unsigned)g_ui.chart.note_count);
+  } else {
+    /* 密度生成失败时退回原始谱面，保证游戏仍可进行 */
+    g_ui.chart = g_ui.chart_source;
+    printf("[AURAUI] 谱面密度生成失败，使用原始谱面\n");
+  }
+}
