+/* 判定结果对应的颜色（音游核心反馈语言） */
+static uint32_t grade_color(aura_grade_t grade)
+{
+  switch (grade) {
+    case AURA_GRADE_PERFECT: return COLOR_GOLD;    /* 完美：金 */
+    case AURA_GRADE_GOOD:    return COLOR_ACCENT;  /* 良好：青 */
+    case AURA_GRADE_MISS:    return COLOR_DANGER;  /* 失误：红 */
+    default:                 return COLOR_MUTED;
+  }
+}
+
+/* -------------------------------------------------------------------------
+ * 判定反馈动画 —— 音符色块按判定结果闪动
+ * =========================================================================
+ * 视觉语言（对应报告 3.2 节"判定结果 → UI 反馈"表）:
+ *   PERFECT → 金色 + 放大（最强正反馈）
+ *   GOOD    → 青色 + 轻微放大
+ *   MISS    → 红色 + 缩小（明确的负反馈）
+ * ---------------------------------------------------------------------- */
+static void note_feedback(aura_grade_t grade)
+{
+  if (g_ui.note == NULL) {
+    return;
+  }
+
+  lv_obj_set_style_bg_color(g_ui.note, lv_color_hex(grade_color(grade)), 0);
+
+  if (grade == AURA_GRADE_PERFECT) {
+    lv_obj_set_size(g_ui.note, 68, 68);
+    lv_obj_set_style_border_width(g_ui.note, 3, 0);
+    lv_obj_set_style_border_color(g_ui.note, lv_color_hex(COLOR_GOLD), 0);
+  } else if (grade == AURA_GRADE_GOOD) {
+    lv_obj_set_size(g_ui.note, 60, 60);
+    lv_obj_set_style_border_width(g_ui.note, 2, 0);
+    lv_obj_set_style_border_color(g_ui.note, lv_color_hex(COLOR_ACCENT), 0);
+  } else if (grade == AURA_GRADE_MISS) {
+    lv_obj_set_size(g_ui.note, 44, 44);
+    lv_obj_set_style_border_width(g_ui.note, 0, 0);
+  }
+}
