{"output": "=== 五种模式的完整时序（从源码提取）===
int vib_play(int pattern)
{
  if (!g_inited)
    {
      return -EPERM;
    }

  switch (pattern)
    {
      /******************************************************************
       * 模式 1：单点短振 —— 50ms ON @60%
       * 应用：Miss 判定反馈 / 走神轻微唤醒
       ******************************************************************/
      case VIB_PATTERN_SINGLE:
        vib_apply(60);
        usleep(50 * 1000);
        vib_apply(0);
        break;

      /******************************************************************
       * 模式 2：双点短振 —— 50 ON - 50 OFF - 50 ON @70%
       * 应用：Good 判定反馈
       ******************************************************************/
      case VIB_PATTERN_DOUBLE:
        vib_apply(70);
        usleep(50 * 1000);
        vib_apply(0);
        usleep(50 * 1000);
        vib_apply(70);
        usleep(50 * 1000);
        vib_apply(0);
        break;

      /******************************************************************
       * 模式 3：三点短振 —— 50ms ON ×3，间隔 50ms @80%
       * 应用：Synapse-N 色点刺激触觉编码
       ******************************************************************/
      case VIB_PATTERN_TRIPLE:
        for (int i = 0; i < 3; i++)
          {
            vib_apply(80);
            usleep(50 * 1000);
            vib_apply(0);
            if (i < 2)
              {
                usleep(50 * 1000);
              }
          }
        break;

      /******************************************************************
       * 模式 4：长振高强 —— 100ms ON @100%
       * 应用：Perfect 判定反馈 / 走神强唤醒
       ******************************************************************/
      case VIB_PATTERN_LONG:
        vib_apply(100);
        usleep(100 * 1000);
        vib_apply(0);
        break;

      /******************************************************************
       * 模式 5：双频交替 —— 50ms 高频 ON - 50ms OFF - 50ms 低频 ON
       *       强度 100% / 40%
       * 应用：N-Back 颜色+位置双属性同时匹配
       * 说明：通过频率切换让用户感知到"两种不同的振动质感"，
       *       高低频在此作为可区分的触觉通道（类似音高）。
       ******************************************************************/
      case VIB_PATTERN_DUALFREQ:
        /* 高频段：100% 强度 */
        vib_set_freq(30000);
        vib_apply(100);
        usleep(50 * 1000);
        vib_apply(0);
        usleep(50 * 1000);

        /* 低频段：40% 强度 */
        vib_set_freq(10000);
        vib_apply(40);
        usleep(50 * 1000);
        vib_apply(0);

        /* 恢复默认频率 */
        vib_set_freq(VIB_PWM_FREQ_HZ);
        break;

      default:
        printf("[VIB] unknown pattern: %d\n", pattern);
        return -EINVAL;
    }

  return 0;
}

